import React, { useState } from 'react';
import './Tabs.css';

const Tabs = () => {
  const [activeTab, setActiveTab] = useState(1);

  const handleTabChange = (tabIndex) => {
    setActiveTab(tabIndex);
  };

  return (
    <div className="popup">
      <div className="tabs">
        <input
          type="radio"
          id="tab1"
          name="tab"
          checked={activeTab === 1}
          onChange={() => handleTabChange(1)}
        />
        <label htmlFor="tab1">FIRST TAB</label>

        <input
          type="radio"
          id="tab2"
          name="tab"
          checked={activeTab === 2}
          onChange={() => handleTabChange(2)}
        />
        <label htmlFor="tab2">SECOND TAB</label>

        <input
          type="radio"
          id="tab3"
          name="tab"
          checked={activeTab === 3}
          onChange={() => handleTabChange(3)}
        />
        <label htmlFor="tab3">THIRD TAB</label>


        <div className="marker">
          <div id="top"></div>
          <div id="bottom"></div>
        </div>
      </div>
    </div>
  );
};

export default Tabs;
